module input

// The set of key codes that the terminal is aware of. These represent
// physical keys on the keyboard. The logical key (or key string)
// is the string that is generated by the key event and that is up
// to the apprt to provide.
//
// Note that these are layout-independent. For example, the "a"
// key on a US keyboard is the same as the "ф" key on a Russian
// keyboard, but both will report the "a" enum value in the key
// event. These values are based on the W3C standard. See:
// https://www.w3.org/TR/uievents-code
pub enum Key {
	unidentified

	// "Writing System Keys" § 3.1.1
	backquote
	backslash
	bracket_left
	bracket_right
	comma
	digit_0
	digit_1
	digit_2
	digit_3
	digit_4
	digit_5
	digit_6
	digit_7
	digit_8
	digit_9
	equal
	intl_backslash
	intl_ro
	intl_yen
	key_a
	key_b
	key_c
	key_d
	key_e
	key_f
	key_g
	key_h
	key_i
	key_j
	key_k
	key_l
	key_m
	key_n
	key_o
	key_p
	key_q
	key_r
	key_s
	key_t
	key_u
	key_v
	key_w
	key_x
	key_y
	key_z
	minus
	period
	quote
	semicolon
	slash

	// "Functional Keys" § 3.1.2
	alt_left
	alt_right
	backspace
	caps_lock
	context_menu
	control_left
	control_right
	enter
	meta_left
	meta_right
	shift_left
	shift_right
	space
	tab
	convert
	kana_mode
	non_convert

	// "Control Pad Section" § 3.2
	delete
	end
	help
	home
	insert
	page_down
	page_up

	// "Arrow Pad Section" § 3.3
	arrow_down
	arrow_left
	arrow_right
	arrow_up

	// "Numpad Section" § 3.4
	num_lock
	numpad_0
	numpad_1
	numpad_2
	numpad_3
	numpad_4
	numpad_5
	numpad_6
	numpad_7
